#!/usr/bin/env bash
# Chapitre « Le header » + commentaires corrigés (seuil xl du header, cloche de la bibliothèque).
# Prérequis : apply-docs-referencement.sh.
# Usage (racine du repo) : bash apply-docs-header.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/interface/header.mdx" 2>/dev/null | grep -qF "title: \"Le header\""; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "title: \"Le référencement\"" "apps/web/content/docs/dev/interface/referencement.mdx" 2>/dev/null || { echo "❌ lancer d'abord apply-docs-referencement.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/index.mdx" "apps/web/src/features/app-shell/Header.tsx" "apps/web/src/features/app-shell/NotificationBell.tsx" "apps/web/src/features/app-shell/navEntries.ts")
CREATED=("apps/web/content/docs/dev/interface/header.mdx")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "title: \"Le header\"" "apps/web/content/docs/dev/interface/header.mdx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
trap 'restore' ERR

mkdir -p "apps/web/content/docs/dev/interface"
